// Input generators for the differential fuzzer (fuzz/run.js). fast-check arbitraries.
// Exports { signup, config }.
//
// Draft 1 ("throw everything at every field") produced 3932 differences but covered only
// 2 of the 7 reachable behaviour changes. Reason, from fuzz/run.js's own rule: an input
// only counts as exercising a change when EVERY OTHER field is valid under zod 3. Draft 1
// randomised all nine fields at once, so nearly every sample was broken in several places
// and could not isolate anything.
//
// So this version is built the other way round:
//
//     sample = a deliberately boring, zod-3-valid base object
//            + a stress value in (usually) exactly ONE field
//
// Each field's stress arbitrary carries the edge cases for the documented zod 4 change on
// that field -- non-RFC UUID version/variant nibbles, IPv6 zone ids, Infinity, integers
// past 2^53, names that are <=80 code points but >80 UTF-16 units, an omitted prefs/port
// (the .default -> .prefault question) -- plus generic junk, so single-field mutants give
// ISOLATED coverage. A smaller tail of 2-3 field mutants is kept on purpose: that is what
// makes the two versions disagree about WHICH field is at fault.
//
// Note: never emit null/undefined at the top level -- run.js's coverage predicates do
// `s.id` / `c.hosts` on the raw sample and would throw.
const fc = require("fast-check");

// weighted oneof, without depending on fast-check's weight option
const w = (...pairs) => fc.oneof(...pairs.flatMap(([n, a]) => Array.from({ length: n }, () => a)));
const OMIT = "�OMIT�"; // sentinel: leave the key out of the object entirely
const drop = (o) => Object.fromEntries(Object.entries(o).filter(([, v]) => v !== OMIT));
const hex = (n) => fc.stringMatching(new RegExp(`^[0-9a-f]{${n}}$`));
const nonString = w([1, fc.constant(OMIT)], [1, fc.constant(null)], [1, fc.integer()], [1, fc.boolean()], [1, fc.constant([])], [1, fc.constant({})]);

/* ------------------------------------------------------------------ id
 * CHANGE: zod 4's z.uuid() checks the version/variant nibbles; src now uses z.guid().
 * Target shape: matches the 8-4-4-4-12 hex shape but is NOT RFC (version nibble outside
 * 1-8, or variant nibble outside 8-b). */
const uuidRfc = w([3, fc.uuid()], [1, fc.uuid().map((s) => s.toUpperCase())]);
const shaped = (version, variant) =>
  fc.tuple(hex(8), hex(4), version, hex(3), variant, hex(3), hex(12))
    .map(([a, b, v, c, u, d, e]) => `${a}-${b}-${v}${c}-${u}${d}-${e}`);
const nonRfcUuid = w(
  [3, shaped(fc.constantFrom("0", "9", "a", "c", "d", "e", "f"), fc.constantFrom("8", "9", "a", "b"))],
  [3, shaped(fc.constantFrom("1", "3", "4", "7", "8"), fc.constantFrom("0", "1", "5", "7", "c", "d", "e", "f"))],
  [1, fc.constantFrom(
    "00000000-0000-0000-0000-000000000000",
    "ffffffff-ffff-ffff-ffff-ffffffffffff",
    "FFFFFFFF-FFFF-FFFF-FFFF-FFFFFFFFFFFF",
  )],
);
const idStress = w(
  [4, nonRfcUuid],
  [2, uuidRfc],
  [2, fc.constantFrom(
    "",
    "not-a-uuid",
    "5f0c2a1e9d3b4c7a8e210b6d4f9a7c33",
    "5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c3",
    "5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c333",
    "{5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c33}",
    "urn:uuid:5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c33",
    " 5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c33",
    "5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c33\n",
    "5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7g33",
    "5f0c2a1e_9d3b_4c7a_8e21_0b6d4f9a7c33",
  )],
  [1, nonString],
);

/* --------------------------------------------------------------- email
 * Not on the known-change list; z.string().email() -> z.email() is a regex swap, so probe
 * the boundary cases where the two regexes could disagree. */
const emailStress = w(
  [2, fc.emailAddress()],
  [4, fc.constantFrom(
    "user@example.com", "a@b.co", "a@b", "a@b.c", "user+tag@sub.example.co.uk",
    "UPPER@EXAMPLE.COM", "a..b@example.com", ".a@example.com", "a.@example.com",
    "a@-example.com", "a@example-.com", "a@exam_ple.com", "a@example..com",
    "a@[127.0.0.1]", "a@[IPv6:::1]", '"quoted local"@example.com',
    "üser@example.com", "user@exämple.com", "user@xn--mple-6qa.com",
    "a@b.com.", "a@@b.com", "a b@example.com", "a!#$%&'*+-/=?^_`{|}~@example.com",
    "a@" + "b".repeat(70) + ".com", "a@1.2.3.4", "", "plainaddress",
  )],
  [1, nonString],
);

/* ---------------------------------------------------------------- name
 * CHANGE: zod 4's .max() counts code POINTS, zod 3 counted UTF-16 code units; src keeps
 * zod 3's measure with a refine. Target shape: length > 80 but [...name].length <= 80. */
const nameStress = w(
  [4, w(
    [2, fc.integer({ min: 41, max: 80 }).map((n) => "\u{1F600}".repeat(n))],   // 2 units / 1 point each
    [1, fc.integer({ min: 41, max: 80 }).map((n) => "\u{1D306}".repeat(n))],
    [1, fc.integer({ min: 21, max: 40 }).map((n) => "\u{1F468}‍\u{1F469}‍\u{1F467}".repeat(1).slice(0, 8) + "a".repeat(n)) ],
  )],
  [2, fc.integer({ min: 81, max: 130 }).map((n) => "a".repeat(n))],            // over the limit either way
  [2, fc.constantFrom(
    "", " ", "\n", "�", "a".repeat(79), "a".repeat(80), "a".repeat(81),
    "\u{1F600}".repeat(40), "\u{1F600}".repeat(41), "a".repeat(79) + "\u{1F600}",
    "é".repeat(45), "\u{1F468}‍\u{1F469}‍\u{1F467}‍\u{1F466}".repeat(4),
    "\uD800", "\uDC00\uD800",
  )],
  [1, fc.string({ unit: "binary", minLength: 1, maxLength: 120 })],
  [1, nonString],
);

/* ----------------------------------------------------------------- age
 * CHANGE: zod 4's .int() means SAFE integer (zod 3 used Number.isInteger).
 * Target shape: Number.isInteger(age) && !Number.isSafeInteger(age). */
const ageStress = w(
