// Input generators for the differential fuzzer (fuzz/run.js). fast-check arbitraries.
// Exports { signup, config }.
//
// DESIGN (draft 3; the earlier drafts are in the run log).
//
// Draft 1 ("throw everything at every field") produced 3932 differences but covered only
// 2 of the 7 reachable behaviour changes. fuzz/run.js only counts an input as exercising a
// change when every OTHER field is valid under zod 3, and a sample with nine independently
// randomised fields is broken in several places at once, so it can isolate nothing.
//
// So samples are built the other way round:
//
//   sample = BASE (an object that is valid under zod 3 AND zod 4)
//          + a stress value in exactly ONE field      <- isolates; this is what gives COVERAGE
//
//   composite pool: BASE + one field PINNED to a value both versions reject
//                        + stress in one or two other fields
//                                                     <- exercises WHICH fields get reported
//
// Pinning the composite pool (signup.plan = "enterprise", config.port = 12345 as a number;
// both versions reject both) keeps composites inside the single "rejected by both, but
// different fields reported" group instead of scattering 1-2 sample groups over the report.
//
// Each field's pool carries the edge cases for the documented zod 4 change on that field
// (non-RFC UUID nibbles, IPv6 zone ids, Infinity, integers past 2^53, names that are <= 80
// code points but > 80 UTF-16 units, an omitted prefs/port for the .default -> .prefault
// question) AND cases for the "silent API moves" that are supposed to be behaviour-neutral
// (z.email, z.url, z.enum, z.record, .prefault), so that a move that is NOT neutral shows up.
//
// Two deliberate asymmetries, so that one group = one mechanism:
//   * signup.ip  gets ONLY zone-id / plain forms: its group isolates the %zone change.
//   * config.hosts gets zone ids AND IPv4-embedded / alternate IPv6 spellings
//     ("0:0:0:0:0:ffff:1.2.3.4"), which zod 3's hand-written regex did not match.
//
// Note: never emit null/undefined at the TOP level -- run.js's coverage predicates do
// `s.id` / `c.hosts` on the raw sample and would throw on null.
const fc = require("fast-check");

/* ------------------------------------------------------------------ helpers */
// weighted oneof, without depending on fast-check's weight option
const w = (...pairs) => fc.oneof(...pairs.flatMap(([n, a]) => Array.from({ length: n }, () => a)));
const pick = (...vs) => fc.constantFrom(...vs);
const OMIT = "�OMIT�"; // sentinel: leave the key out of the object entirely
const drop = (o) => {
  const r = {};
  for (const k of Object.keys(o)) if (o[k] !== OMIT) r[k] = o[k];
  return r;
};
// "wrong type / missing" junk, usable for any field
const other = w(
  [2, fc.constant(OMIT)],
  [1, fc.constant(null)],
  [1, fc.integer()],
  [1, fc.boolean()],
  [1, fc.constant([])],
  [1, fc.constant({})],
  [1, fc.constant(" ")],
);
const hex = (n) => fc.stringMatching(new RegExp(`^[0-9a-f]{${n}}$`));

/* ----------------------------------------------------------------- id
 * CHANGE: zod 4's z.uuid() enforces the RFC 9562 version/variant nibbles; src/schemas.ts
 * uses z.guid() instead, which is meant to be the shape-only check zod 3's .uuid() did.
 * Coverage target: matches 8-4-4-4-12 hex but is NOT RFC (version nibble outside 1-8 or
 * variant nibble outside 8-b). */
const shaped = (ver, vari) =>
  fc.tuple(hex(8), hex(4), ver, hex(3), vari, hex(3), hex(12))
    .map(([a, b, v, c, u, d, e]) => `${a}-${b}-${v}${c}-${u}${d}-${e}`);
const nonRfcGuid = w(
  [3, shaped(pick("0", "9", "a", "c", "d", "e", "f"), pick("8", "9", "a", "b"))],
  [3, shaped(pick("1", "2", "3", "4", "5", "6", "7", "8"), pick("0", "1", "4", "5", "7", "c", "d", "e", "f"))],
  [1, pick(
    "00000000-0000-0000-0000-000000000000",
    "ffffffff-ffff-ffff-ffff-ffffffffffff",
    "FFFFFFFF-FFFF-FFFF-FFFF-FFFFFFFFFFFF",
    "7C9C822E-844B-B6D5-E4A5-8D9348A890E3", // corpus #4's id, upper-cased: non-RFC nibbles
    "06e1162b-72d8-96ee-ec15-8566d817f9cb", // corpus #15's id: version 9, variant e
  )],
);
const idStress = w(
  [5, nonRfcGuid],
  [2, w([1, fc.uuid()], [1, fc.uuid().map((s) => s.toUpperCase())])],
  [3, pick(
    "",
    "not-a-uuid",
    "5f0c2a1e9d3b4c7a8e210b6d4f9a7c33",
    "5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c3",
    "5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c333",
    "{5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c33}",
    "urn:uuid:5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c33",
    " 5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c33",
    "5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c33 ",
    "5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c33\n",
    "5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7g33",
    "5f0c2a1e_9d3b_4c7a_8e21_0b6d4f9a7c33",
  )],
  [1, other],
);

/* -------------------------------------------------------------- email
 * Not on the known-change list: z.string().email() -> z.email() swapped one regex for
 * another, so probe where the two could disagree (and whether zod 4 trims, as its url
 * check does). */
const emailStress = w(
  [2, fc.emailAddress()],
  [6, pick(
    "user@example.com", "a@b.co", "a@b", "a@b.c", "user+tag@sub.example.co.uk",
    "UPPER@EXAMPLE.COM", "a..b@example.com", ".a@example.com", "a.@example.com",
    "a_b@example.com", "a'b@example.com", "-a@example.com", "a@b-.com", "a@-b.com",
    "a@exam_ple.com", "a@example..com", "a@example.com.", "a@[127.0.0.1]",
    "a@[IPv6:::1]", '"quoted local"@example.com', "üser@example.com", "user@exämple.com",
    "user@xn--mple-6qa.com", "a@1.2.3.4", "a@@b.com", "a b@example.com",
    "a!#$%&'*+-/=?^_`{|}~@example.com", "a".repeat(65) + "@example.com",
    "a@" + "b".repeat(70) + ".com", " a@example.com", "a@example.com ",
    "a@example.com\n", "﻿a@example.com", "", "plainaddress",
  )],
  [1, other],
);

/* --------------------------------------------------------------- name
 * CHANGE: zod 4's .max() counts code POINTS; zod 3 counted UTF-16 code units. src keeps
 * zod 3's measure with .refine(s => s.length <= 80).
 * Coverage target: s.length > 80 && [...s].length <= 80. */
const nameStress = w(
  [4, w(
    [3, fc.integer({ min: 41, max: 80 }).map((n) => "\u{1F600}".repeat(n))],
    [1, fc.integer({ min: 41, max: 80 }).map((n) => "\u{1D306}".repeat(n))],
    // 81 UTF-16 units exactly, 81-n code points: over zod 3's limit, under zod 4's
    [2, fc.integer({ min: 1, max: 39 }).map((n) => "a".repeat(81 - 2 * n) + "\u{1F600}".repeat(n))],
  )],
  [3, pick(
    "", " ", "a", "a".repeat(79), "a".repeat(80), "a".repeat(81), "a".repeat(200),
    "\u{1F600}".repeat(40), "\u{1F600}".repeat(41), "a".repeat(79) + "\u{1F600}",
    "é".repeat(45), "é".repeat(45), "\u{1F468}‍\u{1F469}‍\u{1F467}".repeat(4),
    "\uD800", "\uDC00\uD800", "a�b", "  Olu Okafor  ", "\n",
  )],
  [2, fc.string({ unit: "grapheme", maxLength: 100 })],
  [1, fc.string({ unit: "binary", minLength: 1, maxLength: 120 })],
  [1, other],
);

/* ---------------------------------------------------------------- age
 * CHANGE: zod 4's .int() means SAFE integer (zod 3 used Number.isInteger, true for any
 * integral float). Coverage target: Number.isInteger(age) && !Number.isSafeInteger(age). */
const ageStress = w(
  [4, w(
    [3, pick(2 ** 53, 2 ** 53 + 2, 2 ** 54, 2 ** 60, 1e21, 1e30, 9.558522096062336e221, Number.MAX_VALUE)],
    [1, pick(-(2 ** 53), -1e21, -Number.MAX_VALUE)],
    [2, fc.integer({ min: 2, max: 1e9 }).map((n) => n * 2 ** 53)],
  )],
  [3, pick(13, 14, 30, 130, 12, 0, -1, 13.5, 12.9999999999, 0.5, Number.MAX_SAFE_INTEGER, Number.MIN_SAFE_INTEGER)],
  [2, pick(Infinity, -Infinity, NaN, -0, 5e-324, 1e-323)],
  [1, w([1, fc.integer()], [1, fc.double()])],
  [1, w([1, other], [1, pick("20", "13", true, [13])])],
);

/* ------------------------------------------------------------ website
 * Not on the known-change list: z.string().url() -> z.url(). Probe (a) padding with several
 * Unicode whitespace classes -- the URL constructor strips only ASCII space and C0 controls,
 * String.prototype.trim() also strips U+00A0/U+FEFF/U+2007/U+3000 but NOT U+200B -- and
 * (b) protocol/hostname oddities, including hostname-less schemes like javascript:. */
const PAD = ["", " ", "  ", "\n", "\t", "\r\n", " ", "﻿", " ", "　", "​"];
const URLS = ["https://example.com", "http://example.com/a?b=1#c", "https://sub.example.co.uk/p/q"];
const paddedUrl = fc.tuple(pick(...PAD), pick(...URLS), pick(...PAD)).map(([a, u, b]) => a + u + b);
const websiteStress = w(
  [5, paddedUrl],
  [2, fc.webUrl()],
  [4, pick(
    "http://example.com", "https://example.com/a/b?x=1#y", "http://localhost",
    "http://127.0.0.1:8080", "http://[::1]/", "http://xn--80ak6aa92e.com",
    "ftp://files.example.com", "mailto:a@b.com", "javascript:alert(1)",
