// Input generators for the differential fuzzer (fuzz/run.js). fast-check arbitraries.
// Exports { signup, config }.
//
// Why this shape -----------------------------------------------------------------------
// Draft 1 ("throw everything at every field") produced 3932 differences but covered only
// 2 of the 7 reachable behaviour changes. fuzz/run.js counts an input as exercising a
// change only when every OTHER field is valid under zod 3, and randomising nine fields at
// once leaves nearly every sample broken in several places, so nothing can be isolated.
//
// So a sample is built the other way round:
//
//     a boring, zod-3-VALID base object
//   + a stress value in exactly ONE field        (~90% of samples -> isolated coverage)
//   + stress values in two or three fields       (~10%, kept on purpose: that tail is what
//     makes the two versions disagree about WHICH field is at fault)
//
// Each field's stress arbitrary carries the edge cases for the documented zod 4 change on
// that field -- non-RFC UUID version/variant nibbles, IPv6 zone ids, Infinity, integers
// past 2^53, names that are <=80 code points but >80 UTF-16 units, an omitted prefs/port
// for the .default -> .prefault question -- plus near-miss junk around it, and probes for
// two changes that were NOT on the known list but showed up in the diffs: zod 4's ipv6
// accepting forms zod 3's .ip() rejected (uppercase hex, embedded IPv4) and zod 4's
// z.url() trimming the value it returns.
//
// Harness constraints: a sample is always a plain object (run.js's coverage predicates read
// s.id / c.hosts on the raw sample), and the base is always valid under zod 3.
const fc = require("fast-check");

/* ------------------------------------------------------------------ helpers */
// weighted oneof, without relying on fast-check's weight option
const w = (...pairs) => fc.oneof(...pairs.flatMap((p) => Array.from({ length: p[0] }, () => p[1])));
const of = (...vs) => fc.constantFrom(...vs);

// sentinel: "leave this key out of the object entirely"
const OMIT = "�__omit__�";
const prune = (o) => {
  const out = {};
  for (const k of Object.keys(o)) if (o[k] !== OMIT) out[k] = o[k];
  return out;
};

const hex = (n) => fc.stringMatching(new RegExp("^[0-9a-f]{" + n + "}$"));
// wrong TYPE (or absent) for a field that wants a string
const notAString = w(
  [2, fc.constant(OMIT)],
  [1, fc.constant(null)],
  [1, fc.constant(12)],
  [1, fc.constant(true)],
  [1, fc.constant([])],
  [1, fc.constant({})],
);

/* ----------------------------------------------------------------------- id
 * CHANGE: zod 4's z.uuid() enforces the RFC 9562 version/variant nibbles; src/schemas.ts
 * uses z.guid() to keep zod 3's shape-only check. Target shape for coverage: matches
 * 8-4-4-4-12 hex but NOT the RFC nibble pattern. */
const shaped = (version, variant) =>
  fc.tuple(hex(8), hex(4), version, hex(3), variant, hex(3), hex(12))
    .map((p) => p[0] + "-" + p[1] + "-" + p[2] + p[3] + "-" + p[4] + p[5] + "-" + p[6]);

const nonRfcGuid = w(
  // version nibble outside 1-8 (variant still legal)
  [3, shaped(of("0", "9", "a", "b", "c", "d", "e", "f"), of("8", "9", "a", "b"))],
  // variant nibble outside 8-b (version still legal)
  [3, shaped(of("1", "2", "3", "4", "5", "6", "7", "8"), of("0", "1", "2", "5", "6", "7", "c", "d", "e", "f"))],
  // both nibbles wrong, and the special nil / max ids zod 4 allow-lists
  [1, shaped(of("0", "f"), of("0", "f")).map((s) => s.toUpperCase())],
  [1, of(
    "00000000-0000-0000-0000-000000000000",
    "ffffffff-ffff-ffff-ffff-ffffffffffff",
    "FFFFFFFF-FFFF-FFFF-FFFF-FFFFFFFFFFFF",
  )],
);

const idStress = w(
  [5, nonRfcGuid],
  [2, w([2, fc.uuid()], [1, fc.uuid().map((s) => s.toUpperCase())])],
  [2, of(
    "",
    "not-a-uuid",
    "5f0c2a1e9d3b4c7a8e210b6d4f9a7c33",
    "5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c3",
    "5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c333",
    "{5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c33}",
    "urn:uuid:5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c33",
    " 5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c33",
    "5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c33\n",
    "5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7g33",
    "5f0c2a1e_9d3b_4c7a_8e21_0b6d4f9a7c33",
  )],
  [1, notAString],
);

/* -------------------------------------------------------------------- email
 * Not on the known-change list: z.string().email() -> z.email() is a regex swap, so probe
 * the places where the two regexes could disagree. */
const emailStress = w(
  [2, fc.emailAddress()],
  [5, of(
    "user@example.com", "a@b.co", "a@b", "a@b.c", "user+tag@sub.example.co.uk",
    "UPPER@EXAMPLE.COM", "a..b@example.com", ".a@example.com", "a.@example.com",
    "a@-example.com", "a@example-.com", "a@exam_ple.com", "a@example..com",
    "a@[127.0.0.1]", "a@[IPv6:::1]", '"quoted local"@example.com',
    "üser@example.com", "user@exämple.com", "user@xn--mple-6qa.com",
    "a@b.com.", "a@@b.com", "a b@example.com", "a!#$%&'*+-/=?^_`{|}~@example.com",
    "a@1.2.3.4", "a@" + "b".repeat(70) + ".com", " a@b.com", "a@b.com ", "", "plainaddress",
  )],
  [1, notAString],
);

/* --------------------------------------------------------------------- name
 * CHANGE: zod 4's .max() counts code POINTS, zod 3 counted UTF-16 code units;
 * src/schemas.ts keeps zod 3's measure with a .refine(). Target shape for coverage:
 * name.length > 80 && [...name].length <= 80. */
const nameStress = w(
  [4, w(
    // 2 UTF-16 units per code point: 41..80 emoji = 82..160 units, 41..80 points
    [3, fc.integer({ min: 41, max: 80 }).map((n) => "\u{1F600}".repeat(n))],
    [1, fc.integer({ min: 41, max: 80 }).map((n) => "\u{1D306}".repeat(n))],
    // exactly 81 units, 81-n points: the narrowest possible straddle of the limit
    [2, fc.integer({ min: 1, max: 39 }).map((n) => "a".repeat(81 - 2 * n) + "\u{1F600}".repeat(n))],
  )],
  [2, fc.integer({ min: 81, max: 140 }).map((n) => "a".repeat(n))],
  [2, of(
    "", " ", "a", "a".repeat(79), "a".repeat(80), "a".repeat(81),
    "\u{1F600}".repeat(40), "\u{1F600}".repeat(41),
    "a".repeat(79) + "\u{1F600}", "a".repeat(80) + "\u{1F600}",
    "é".repeat(45), "\u{1F468}‍\u{1F469}‍\u{1F467}".repeat(10),
    "\uD83D", "\uDE00\uD83D", "Ada�Lovelace", "  Ada  ", "\n",
  )],
  [1, fc.string({ unit: "binary", minLength: 1, maxLength: 120 })],
  [1, notAString],
);

/* ---------------------------------------------------------------------- age
 * CHANGE: zod 4's .int() means SAFE integer (zod 3 used Number.isInteger).
 * Target shape for coverage: Number.isInteger(age) && !Number.isSafeInteger(age). */
const ageStress = w(
  [4, w(
    [3, of(9007199254740992, 9007199254740994, 2 ** 54, 2 ** 60, 1e21, 1e30, 1.7976931348623157e308)],
    [2, fc.integer({ min: 13, max: 1000000 }).map((n) => n * 9007199254740992)],
    [1, of(-9007199254740992, -1e21, -1.7976931348623157e308)],
  )],
  [2, of(13, 14, 30, 130, 12, 0, -1, 13.5, 12.999999999, 0.5, 9007199254740991, -9007199254740991)],
  [2, of(Infinity, -Infinity, NaN, -0, 5e-324)],
  [1, w([1, fc.integer()], [1, fc.double()])],
  [1, w(
    [2, fc.constant(OMIT)],
    [1, fc.constant(null)],
    [1, fc.constant("30")],
    [1, fc.constant(true)],
    [1, fc.constant([13])],
