/* ------------------------------------------------------------------ website
 * Not on the known-change list. z.string().url() -> z.url(): zod 4 trims the string and
 * writes the trimmed value back, and its notion of "whitespace" is String.prototype.trim
 * (NBSP, BOM, U+2028 ...) rather than the WHATWG URL parser's "C0 control or space".
 * So pad valid URLs with assorted whitespace on both sides and watch the parsed value. */
const URLS = ["https://example.com", "http://example.com/a?b=1#c", "https://sub.example.co.uk/p"];
const PAD = ["", " ", "  ", "\n", "\t", " ", "﻿", " ", "​", ""];
const paddedUrl = fc.tuple(of(...URLS), of(...PAD), of(...PAD)).map((p) => p[1] + p[0] + p[2]);
const websiteStress = w(
  [4, paddedUrl],
  [2, fc.webUrl()],
  [3, of(
    "http://localhost", "http://127.0.0.1:8080", "http://[::1]/", "ftp://files.example.com",
    "mailto:a@b.com", "javascript:alert(1)", "data:text/plain,hi", "tel:+15551234",
    "//example.com", "example.com", "http://", "http:/example.com", "http://exa mple.com",
    "http://ex..com", "http://-a.com", "http://a_b.com", "HTTP://EXAMPLE.COM",
    "http://example.com:99999", "file:///etc/passwd", "http://user:pw@example.com/",
    "https://éxample.com", "https://example.com/é", "http://1.2.3.4",
    "http://example", "https://example.com/", "",
  )],
  [1, notAString],
);

/* ----------------------------------------------------------------------- ip
 * CHANGE: zod 4's z.ipv6() rejects a zone index; src/schemas.ts re-adds it with a refine
 * that splits on the FIRST "%", requires a non-empty zone and validates the head with
 * z.ipv6(). Target shape for coverage: the string contains "%".
 * Also probed here (not on the known list): uppercase hex and embedded-IPv4 (dotted quad)
 * IPv6 forms, which zod 4's ipv6 accepts and zod 3's .ip() did not. */
const PLAIN6 = [
  "fe80::1", "::1", "::", "2001:db8::1", "fd00::a:b:c:d",
  "2001:0db8:0000:0000:0000:0000:0000:0001", "2001:db8:0:0:1::1",
];
const UPPER6 = ["FE80::1", "2001:DB8::1", "FD00::A:B"];
const MAPPED6 = ["::ffff:1.2.3.4", "::ffff:192.168.0.1", "64:ff9b::1.2.3.4", "0:0:0:0:0:ffff:1.2.3.4", "::1.2.3.4"];
const ZONES = ["eth0", "en0", "lo", "1", "0", "eth0.5", "%", "a b", "σ", "eth0%eth1", ""];

const zonedIp = fc.tuple(of(...PLAIN6.concat(UPPER6, MAPPED6)), of(...ZONES)).map((p) => p[0] + "%" + p[1]);

// string-valued ip candidates (no OMIT/type junk: these are also used as array elements)
const ipStrings = w(
  [5, zonedIp],
  [2, of(...PLAIN6)],
  [1, of(...UPPER6)],
  [2, of(...MAPPED6)],
  [2, w([1, fc.ipV4()], [1, fc.ipV6()])],
  [2, of(
    "10.0.0.1", "203.0.113.7", "255.255.255.255", "256.1.1.1", "1.2.3", "1.2.3.4.5",
    "01.2.3.4", "1.2.3.04", "0x7f.0.0.1", "10.0.0.1%eth0", "[::1]", "::1 ", " ::1",
    "fe80::1/64", "fe80::1%eth0 ", "%eth0", "%", "not-an-ip%eth0", "example.com", "",
    "1:2:3:4:5:6:7:8:9", "g::1", "12345::1",
  )],
);
const ipStress = w([9, ipStrings], [1, notAString]);

/* --------------------------------------------------------------------- plan */
const planStress = w(
  [3, of("free", "pro", "team")],
  [3, of("Free", "FREE", "basic", "enterprise", " free", "free ", "", "0")],
  [1, notAString],
);

/* -------------------------------------------------------------------- flags
 * z.record(z.boolean()) -> z.record(z.string(), z.boolean()). Keys worth probing are the
 * prototype-ish ones: zod 3 and zod 4 build the output object differently, so whether an
 * own "__proto__" key survives (and is checked at all) can differ. Built with
 * defineProperty so "__proto__" really is an own key and not a prototype assignment. */
const flagKey = of("beta", "newCheckout", "__proto__", "constructor", "prototype", "toString", "valueOf", "a b", "", "0");
const flagValue = w(
  [4, fc.boolean()],
