// Input generators for the differential fuzzer (fuzz/run.js). fast-check arbitraries.
// Exports { signup, config }.
//
// WHY THIS SHAPE
// Draft 1 ("throw everything at every field") produced 3932 differences but COVERED only
// 2 of the 7 reachable behaviour changes. run.js only counts an input as exercising a
// change when every OTHER field is valid under zod 3; draft 1 randomised all nine signup
// fields at once, so nearly every sample was broken in three or four places and could
// isolate nothing.
//
// So a sample here is:   a boring, zod-3-valid BASE object
//                      + a stress value in exactly ONE field   (~80% of samples)
//                      + a smaller tail of two-field mutants   (~20%)
// The single-field mutants buy isolated coverage; the two-field tail is what makes the two
// versions disagree about WHICH field is at fault (the "rejected by both" groups).
//
// Every stress set carries (a) the documented zod 4 edge cases for that field and (b) a few
// deliberately LABELLED constants -- e.g. "https://nbsp.example.com" padded with U+00A0, or
// a fixed IPv6 taxonomy -- so that the three examples run.js prints per group identify the
// sub-case instead of showing unreadable random junk.
//
// Invariant: never emit a non-object at the top level. run.js's coverage predicates read
// s.id / s.name / c.hosts off the raw sample and would throw on null/undefined.
const fc = require("fast-check");

/* ------------------------------------------------------------------- helpers */
// weighted oneof, without depending on fast-check's weight option
const w = (...pairs) => fc.oneof(...pairs.flatMap(([n, a]) => Array.from({ length: n }, () => a)));
const pick = (...xs) => fc.constantFrom(...xs);
const hex = (n) => fc.stringMatching(new RegExp("^[0-9a-f]{" + n + "}$"));
const OMIT = "�OMIT�"; // sentinel: leave the key out of the object entirely
const omit = fc.constant(OMIT);
const build = (base, over) => {
  const merged = Object.assign({}, base, over);
  const out = {};
  for (const k of Object.keys(merged)) if (merged[k] !== OMIT) out[k] = merged[k];
  return out;
};
const missing = (...extra) => w([2, omit], [1, fc.constant(null)], [1, fc.integer()], ...extra.map((e) => [1, fc.constant(e)]));

/* ---------------------------------------------------------------- signup.id
 * CHANGE: zod 4's z.uuid() enforces the RFC 9562 version/variant nibbles; src uses z.guid(),
 * the shape-only check zod 3's .uuid() actually performed.
 * Coverage target: matches 8-4-4-4-12 hex but version nibble outside 1-8 or variant outside
 * 8-b, with every other field valid. */
const uuidShaped = (ver, vari) =>
  fc.tuple(hex(8), hex(4), ver, hex(3), vari, hex(3), hex(12))
    .map((p) => p[0] + "-" + p[1] + "-" + p[2] + p[3] + "-" + p[4] + p[5] + "-" + p[6]);
const RFC_VER = pick("1", "2", "3", "4", "5", "6", "7", "8");
const RFC_VAR = pick("8", "9", "a", "b", "A", "B");
const BAD_VER = pick("0", "9", "a", "b", "c", "d", "e", "f");
const BAD_VAR = pick("0", "1", "2", "3", "4", "5", "6", "7", "c", "d", "e", "f");
const idStress = w(
  [3, uuidShaped(BAD_VER, RFC_VAR)],
  [3, uuidShaped(RFC_VER, BAD_VAR)],
  [1, uuidShaped(BAD_VER, BAD_VAR)],
  [2, uuidShaped(RFC_VER, RFC_VAR)],
  [1, pick(
    "00000000-0000-0000-0000-000000000000",
    "ffffffff-ffff-ffff-ffff-ffffffffffff",
    "5F0C2A1E-9D3B-4C7A-8E21-0B6D4F9A7C33")],
  [2, pick(
    "", "not-a-uuid",
    "5f0c2a1e9d3b4c7a8e210b6d4f9a7c33",
    "{5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c33}",
    "urn:uuid:5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c33",
    "5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c3",
    "5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c333",
    " 5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c33",
    "5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7c33\n",
    "5f0c2a1e-9d3b-4c7a-8e21-0b6d4f9a7g33")],
  [1, missing()],
);

/* -------------------------------------------------------------- signup.email
 * Not on the known-change list: z.string().email() -> z.email() is a regex swap, so probe the
 * boundaries where the two regexes could disagree (dots, TLD length, IP/bracket hosts,
 * quoted local parts, non-ASCII). */
const emailStress = w(
  [3, pick(
    "sam.okafor@example.com", "a@b.co", "user+tag@sub.example.co.uk", "UPPER@EXAMPLE.COM",
    "a!#$%&'*+-/=?^_`{|}~@example.com", "a@1.2.3.4")],
  [3, pick(
    "a@b", "a@b.c", "a..b@example.com", ".a@example.com", "a.@example.com",
    "a@-example.com", "a@example-.com", "a@exam_ple.com", "a@example..com",
    "a@[127.0.0.1]", "a@[IPv6:::1]", "\"quoted local\"@example.com",
    "üser@example.com", "user@exämple.com", "user@xn--mple-6qa.com",
    "a@b.com.", "a@@b.com", "a b@example.com", "", "plainaddress",
    "a@" + "b".repeat(70) + ".com")],
  [1, fc.emailAddress()],
  [1, missing()],
);

/* --------------------------------------------------------------- signup.name
 * CHANGE: zod 4's .max() counts Unicode code POINTS; zod 3 counted UTF-16 code units.
 * src keeps zod 3's measure with .refine(s => s.length <= 80).
 * Coverage target: name.length > 80 but [...name].length <= 80. */
const GRIN = "😀";                               // U+1F600, 2 code units
const TETRA = "𝌆";                              // U+1D306, 2 code units
const FAMILY = "👨‍👩‍👧"; // 8 units / 5 points
const nameStress = w(
  [3, fc.integer({ min: 41, max: 80 }).map((n) => GRIN.repeat(n))],   // 82..160 units, 41..80 points
  [1, fc.integer({ min: 41, max: 80 }).map((n) => TETRA.repeat(n))],
  [1, fc.integer({ min: 11, max: 16 }).map((n) => FAMILY.repeat(n))], // 88..128 units, 55..80 points
  [2, pick(
    "Sam Okafor", "Sofía Perlman",
    "a".repeat(79), "a".repeat(80), "a".repeat(81), "a".repeat(160),
    "", " ", " ", "\n",
    "é".repeat(45), "a".repeat(79) + GRIN, GRIN.repeat(40), GRIN.repeat(41),
    "\uD800", "\uDC00\uD800")],
  [1, fc.string({ unit: "grapheme", maxLength: 120 })],
  [1, fc.string({ unit: "binary", maxLength: 120 })],
  [1, missing()],
);

/* ---------------------------------------------------------------- signup.age
 * CHANGE: zod 4's .int() means SAFE integer (zod 3 used Number.isInteger, true for any
 * integral float). Coverage target: Number.isInteger(age) && !Number.isSafeInteger(age). */
const ageStress = w(
  [4, pick(2 ** 53, 2 ** 53 + 2, 2 ** 54, 2 ** 60, 1e21, 1e30, Number.MAX_VALUE,
           -(2 ** 53), -1e21, 9007199254740994)],
  [2, pick(13, 14, 30, 130, 12, 0, -1, 13.5, 0.5, 12.9999999999,
           Number.MAX_SAFE_INTEGER, -Number.MAX_SAFE_INTEGER)],
  [2, pick(Infinity, -Infinity, NaN, -0, 5e-324)],
  [1, w([1, fc.integer({ min: -100, max: 1000000 })], [1, fc.double()])],
  [1, missing("20", true)],
);

/* ------------------------------------------------------------ signup.website
 * Not on the known-change list. zod 3 handed the RAW string to new URL(); zod 4's z.url()
 * appears to trim first and to store the TRIMMED string. The padded constants are labelled
 * by hostname so the printed examples say which padding character is responsible:
 *   sp/tab/nl   -> ASCII whitespace, which the WHATWG URL parser already strips
 *   nbsp/bom/emsp -> whitespace that new URL() does NOT strip but String.trim() does */
const PADDED_URL = pick(
  " https://sp.example.com ",
  "\thttps://tab.example.com\t",
  "\nhttps://nl.example.com\n",
  " https://sp-lead.example.com",
  "https://sp-trail.example.com ",
  " https://nbsp.example.com",
  "https://nbsp-trail.example.com ",
  "﻿https://bom.example.com",
  "https://bom-trail.example.com﻿",
  " https://emsp.example.com ");
const CLEAN_URL = pick(
  "https://example.com", "https://example.com/", "http://example.com/a?b=1#c",
  "https://sub.example.co.uk/p", "http://127.0.0.1:8080/", "http://[::1]/",
  "HTTP://EXAMPLE.COM", "http://xn--80ak6aa92e.com", "https://éxample.com");
const ODD_URL = pick(
  "ftp://files.example.com", "mailto:a@b.com", "javascript:alert(1)", "data:text/plain,hi",
  "tel:+15551234", "//example.com", "example.com", "http://", "http:/example.com",
  "http://exa mple.com", "http://ex..com", "http://-a.com", "http://a_b.com",
  "http://example.com:99999", "file:///etc/passwd", "http://user:pw@example.com/",
  "http://example", "http://localhost", "");
const websiteStress = w(
  [4, PADDED_URL],
  [2, CLEAN_URL],
  [2, ODD_URL],
  [1, fc.webUrl()],
  [2, missing()],
);

/* ----------------------------------------------------------------- signup.ip
 * CHANGE: zod 4's z.ipv6() rejects zone ids; src re-adds them with `zonedIpv6`.
 * Coverage target: the string contains "%".
 * The taxonomy is fixed and readable on purpose -- zod 3's ip() regex only had ONE zone
 * branch (lowercase fe80 + alphanumeric zone), so these constants separate "zone id" from
 * "uppercase", "not fe80", "odd zone characters" and "IPv4 embedded in IPv6". */
const ZONED = pick(
  "fe80::1%eth0", "fe80::1%wlan0", "fe80::1%1",       // zod 3 accepted these
  "FE80::1%eth0", "::1%lo", "2001:db8::1%eth0", "fd00::1%eth0",
  "fe80::1%eth0.5", "fe80::1%a b", "fe80::1%σ", "fe80::1%%", "fe80::1%eth0 ",
  "fe80::1%", "%eth0", "10.0.0.1%eth0", "not-an-ip%eth0", "::ffff:1.2.3.4%eth0");
const EMBEDDED = pick(
  "::ffff:192.168.0.1", "::1.2.3.4", "64:ff9b::1.2.3.4", "2001:db8::a:1.2.3.4",
  "0:0:0:0:0:ffff:1.2.3.4", "1:2:3:4:5:6:1.2.3.4", "::ffff:0:1.2.3.4");
const PLAIN6 = pick(
  "::1", "::", "fe80::1", "FD00::A:B", "2001:0db8:0000:0000:0000:ff00:0042:8329",
  "2001:db8::1", "01234::1", "12345::1", ":::1");
const V4 = pick(
  "0.0.0.0", "255.255.255.255", "10.0.0.9", "192.168.0.1", "203.0.113.7",
  "1.2.3.04", "01.2.3.4", "256.1.1.1", "1.2.3", "1.2.3.4.5", "0x7f.0.0.1", "1.2.3.4 ");
const ipStress = w(
  [5, ZONED], [2, EMBEDDED], [2, PLAIN6], [3, V4],
  [1, pick("", "localhost", "example.com", "::ffff:999.1.1.1")],
  [1, missing()],
);

/* --------------------------------------------------------------- signup.plan */
const planStress = w(
  [4, pick("free", "pro", "team")],
  [2, pick("Free", "FREE", "basic", "", "free ", "enterprise")],
  [1, missing(true)],
);

/* -------------------------------------------------------------- signup.flags
 * z.record(z.boolean()) -> z.record(z.string(), z.boolean()). Not on the known-change list,
 * but record key handling is exactly where zod 4 added prototype-pollution guards, so a
 * third of the samples carry an OWN "__proto__" key (Object.fromEntries defines it as a
 * data property, which is what JSON.parse of real traffic also produces). "constructor",
 * "toString" and "valueOf" are in the key pool as controls. */
const FLAG_KEY = pick("beta", "newCheckout", "dark-mode", "", "a b", "0",
                      "toString", "constructor", "valueOf", "hasOwnProperty");
const FLAG_VAL = w([4, fc.boolean()], [2, pick(1, 0, "true", "false", null, [], { polluted: true })]);
const plainFlags = fc.array(fc.tuple(FLAG_KEY, FLAG_VAL), { maxLength: 4 }).map((es) => Object.fromEntries(es));
const protoFlags = fc.tuple(FLAG_VAL, fc.boolean())
  .map(([v, beta]) => Object.fromEntries([["beta", beta], ["__proto__", v]]));
const flagsStress = w(
  [4, plainFlags],
  [3, protoFlags],
  [1, pick({}, { beta: true }, { beta: false, newCheckout: true })],
  [1, missing("x")],
);

/* -------------------------------------------------------------- signup.prefs
 * CHANGE: .default({}) -> .prefault({}) and the inner .default("3") -> .prefault("3").
 * Coverage target: prefs is absent, so the fallback object has to be fed through the
 * object schema and its inner defaults. (The base object has no prefs, so most samples
