  [4, omit],
  [2, fc.constant({})],
  [2, pick({ theme: "dark" }, { theme: "light" }, { retries: "5" }, { retries: "0" },
           { theme: "dark", retries: "7" })],
  [2, pick({ theme: "blue" }, { theme: "" }, { retries: "abc" }, { retries: "" },
           { retries: 5 }, { retries: null }, { theme: null }, { extra: 1 })],
  [1, pick(null, [], "x", 1, true)],
);

/* ------------------------------------------------------------- config.port */
