  [4, pick(Infinity, -Infinity)],
  [2, pick(NaN, 0, -0, -1, 5e-324, 1e21, 2 ** 53 + 2, Number.MAX_VALUE, Number.MIN_VALUE)],
  [2, pick(5000, 1, 0.5, 30000, 250)],
  [2, w([1, fc.integer({ min: -10, max: 1000000 })], [1, fc.double()])],
  [2, omit],
