  [3, sOne("id")], [2, sOne("email")], [3, sOne("name")], [4, sOne("age")],
  [3, sOne("website")], [5, sOne("ip")], [1, sOne("plan")], [2, sOne("flags")], [3, sOne("prefs")],
  [1, sTwo("age", "website")], [1, sTwo("ip", "email")], [1, sTwo("name", "age")],
  [1, sTwo("flags", "ip")], [1, sTwo("prefs", "plan")], [1, sTwo("age", "ip")],
);

const CBASE = { hosts: ["203.0.113.7"] };
const CSTRESS = { port: portStress, hosts: hostsStress, timeoutMs: timeoutStress };
const cOne = (f) => CSTRESS[f].map((v) => build(CBASE, { [f]: v }));
const cTwo = (f, g) => fc.tuple(CSTRESS[f], CSTRESS[g]).map(([a, b]) => build(CBASE, { [f]: a, [g]: b }));

const config = w(
  [2, cOne("port")], [6, cOne("hosts")], [5, cOne("timeoutMs")],
  [2, cTwo("hosts", "timeoutMs")], [1, cTwo("port", "hosts")], [1, cTwo("port", "timeoutMs")],
);

module.exports = { signup, config };

